  AlertCircleIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/* The icon rule's example: ordinary actions, because the point of that card is
   one size and one stroke weight rather than the glyphs themselves. */
export const PreviewIcon = icon(PlayIcon, "PreviewIcon")
export const NarrowIcon = icon(FilterIcon, "NarrowIcon")
export const ExportIcon = icon(Download01Icon, "ExportIcon")
export const DeleteIcon = icon(Delete02Icon, "DeleteIcon")

/** The two a row carries. Named for the row, not for the glyph. */
export const EditRowIcon = icon(PencilEdit02Icon, "EditRowIcon")

/** Sorting: the active direction, and the affordance on a column that is not sorted. */
export const SortAscIcon = icon(ArrowUp01Icon, "SortAscIcon")
export const SortDescIcon = icon(ArrowDown01Icon, "SortDescIcon")
export const SortableIcon = icon(ArrowDataTransferVerticalIcon, "SortableIcon")

/** Direction, which is what tells the two neutral chips apart. */
export const InboundIcon = icon(ArrowDownLeft01Icon, "InboundIcon")
export const OutboundIcon = icon(ArrowUpRight01Icon, "OutboundIcon")

/** The four call states. */
export const CompletedIcon = icon(CheckmarkCircle02Icon, "CompletedIcon")
export const FailedIcon = icon(CancelCircleIcon, "FailedIcon")
export const RunningIcon = icon(Clock01Icon, "RunningIcon")
export const ScheduledIcon = icon(Calendar03Icon, "ScheduledIcon")

/* The close control on the drawer demo's header — the house shape is a title,
   a description and this button, with no icon tile beside the title. */
export const CloseIcon = icon(Cancel01Icon, "CloseIcon")

export const RowMenuIcon = icon(MoreHorizontalIcon, "RowMenuIcon")
export const SearchIcon = icon(Search01Icon, "SearchIcon")

/* The multi-step form explains its fields with an (i) beside the label rather
   than a line under it — the reference it is built from does, and a screen
   uses one language for all of its fields or the other. */
export const HintIcon = icon(InformationCircleIcon, "HintIcon")
export const WarningIcon = icon(Alert02Icon, "WarningIcon")

/** A bare tick, for a step already done. `CompletedIcon` is a circled one and
    would sit inside the stepper's own circle. */
export const StepDoneIcon = icon(Tick02Icon, "StepDoneIcon")

/* The rail's disclosure chevron. It points down when the section is open and
   is rotated a quarter turn when it is not, so one glyph carries both states
   rather than two glyphs that have to be told apart. */
export const SectionToggleIcon = icon(ArrowDown01Icon, "SectionToggleIcon")

/* The tabs demo. One glyph per view of the same call, each naming what that
   view holds — the bar is the thing being demonstrated, so the labels carry
   an icon the way a real settings or record bar does. */
export const TranscriptIcon = icon(BubbleChatIcon, "TranscriptIcon")
export const ModelIcon = icon(CpuIcon, "ModelIcon")
export const CostIcon = icon(Coins01Icon, "CostIcon")

/* The header control that hands this exact topic to someone. The tick is the
   same glyph a finished step uses — one "done" mark across the reference,
   rather than a second one that has to be learned. */
export const CopyLinkIcon = icon(CopyLinkGlyph, "CopyLinkIcon")
export const CopiedIcon = icon(Tick02Icon, "CopiedIcon")

/* Copies a whole section out as a skill file. */
export const CopySkillIcon = icon(Copy01Icon, "CopySkillIcon")

/* The three states that are not the populated one, each named for the state
   rather than the glyph: nothing here yet, nothing matched, and it broke. */
export const NoResultsIcon = icon(SearchRemoveIcon, "NoResultsIcon")
export const SourceIcon = icon(BookOpen02Icon, "SourceIcon")
export const RetryIcon = icon(RefreshIcon, "RetryIcon")

/* The ring's way back up a level: from one section's topics to the five
   sections themselves. Named for where it goes rather than for the arrow,
   because the same glyph points back to two different places on this page. */
export const AllSectionsIcon = icon(ArrowLeft01Icon, "AllSectionsIcon")

/** The trailing mark on a section row on the overview. */
export const OpenSectionIcon = icon(ArrowRight01Icon, "OpenSectionIcon")

/* One per section on the overview. Named for the shelf, not the glyph, and
   present for the reason the house rules allow an icon in a list at all: five
   cards that differ only by a word are quicker to tell apart with a mark than
   without one. Nothing else on that page carries an icon. */
export const FoundationsIcon = icon(ColorsIcon, "FoundationsIcon")
export const MotionSectionIcon = icon(
  EaseCurveControlPointsIcon,
  "MotionSectionIcon",
)
export const PatternsIcon = icon(DashboardSquare01Icon, "PatternsIcon")
export const CustomComponentsIcon = icon(CubeIcon, "CustomComponentsIcon")
export const ShadcnComponentsIcon = icon(ComponentIcon, "ShadcnComponentsIcon")

/* The Icons tile's subject: one everyday glyph from the set the product draws
   from, set on its construction sheet by the tile's drawing. */
export const IconsTopicGlyph = icon(Home01Icon, "IconsTopicGlyph")

/* The index-page demo's header action. */
export const StartCallIcon = icon(CallOutgoing01Icon, "StartCallIcon")

/* The scenarios index: its two header tiles, the admin scope, and the row's
   one icon action. */
export const CreateScenarioIcon = icon(PlusSignIcon, "CreateScenarioIcon")
export const PlaygroundIcon = icon(Robot01Icon, "PlaygroundIcon")
export const OrganisationIcon = icon(Building02Icon, "OrganisationIcon")
export const CreateTemplateIcon = icon(FileValidationIcon, "CreateTemplateIcon")
export const ActiveIcon = icon(CheckmarkCircle02Icon, "ActiveIcon")
export const DeletedIcon = icon(Delete02Icon, "DeletedIcon")

/* The knowledge base's five ways in, as its header tiles. */
export const AddUrlIcon = icon(GlobalIcon, "AddUrlIcon")
export const AddFilesIcon = icon(File01Icon, "AddFilesIcon")
export const AddTextIcon = icon(TextIcon, "AddTextIcon")
export const CreateFolderIcon = icon(FolderAddIcon, "CreateFolderIcon")
export const SyncDocumentsIcon = icon(FolderSyncIcon, "SyncDocumentsIcon")

/* Surfaces: the demos under Components › Choosing a surface. */
export const ArchiveIcon = icon(Archive02Icon, "ArchiveIcon")
export const PreviousRecordIcon = icon(ArrowUp01Icon, "PreviousRecordIcon")
export const NextRecordIcon = icon(ArrowDown01Icon, "NextRecordIcon")
export const CreateInListIcon = icon(PlusSignIcon, "CreateInListIcon")
export const CopyKeyIcon = icon(Copy01Icon, "CopyKeyIcon")

/* Creation flow: the ways to start a scenario, and the industries its
   templates are filed under. */
export const StartBlankIcon = icon(DashedLineCircleIcon, "StartBlankIcon")
export const ChooseStartIcon = icon(ArrowRight02Icon, "ChooseStartIcon")
export const StepBackIcon = icon(ArrowLeft02Icon, "StepBackIcon")
export const BuildWithAiIcon = icon(SparklesIcon, "BuildWithAiIcon")
export const HealthcareIcon = icon(Hospital01Icon, "HealthcareIcon")
export const TelecomIcon = icon(SmartPhone01Icon, "TelecomIcon")
export const BankingIcon = icon(BankIcon, "BankingIcon")
export const RestaurantsIcon = icon(Restaurant01Icon, "RestaurantsIcon")
export const RetailIcon = icon(ShoppingBag01Icon, "RetailIcon")
export const RealEstateIcon = icon(RealEstate01Icon, "RealEstateIcon")

/* JSON: the fold toggle on an object's opening line, and copy. */
export const FoldIcon = icon(ArrowRight01Icon, "FoldIcon")
export const CopyJsonIcon = icon(Copy01Icon, "CopyJsonIcon")

/* Alerts: the error intent's glyph. Neutral, success and warning reuse
   HintIcon, CompletedIcon and WarningIcon. */
export const ErrorAlertIcon = icon(AlertCircleIcon, "ErrorAlertIcon")

import * as React from "react"

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { cn } from "@/lib/utils"

/**
 * The one table every reference list on this page is built from.
 *
 * Nearly all of them are the same three things — a specimen, its name, and
 * what it is for — and they had drifted into five different two-column grids
 * that each aligned slightly differently. One component means one row height,
 * one header treatment, and one place to change any of it.
 *
 * Cells take nodes, not strings, so a live demo sits in a column beside the
 * prose rather than in a separate block underneath it.
 */

export type ReferenceColumn = {
  header: string
  /**
   * A literal width class — Tailwind only emits a utility it can see spelled
   * out. Leave it off the column that should take the remaining width.
   */
  width?: string
}

export type ReferenceRow = {
  key: string
  cells: React.ReactNode[]
}

export function ReferenceTable({
  columns,
  rows,
}: {
  columns: ReferenceColumn[]
  rows: ReferenceRow[]
}) {
  return (
    <div className="overflow-hidden rounded-lg border">
      {/* Fixed layout, because the widths above are the whole point: with the
          default auto layout a long cell quietly widens its column and every
          table on the page ends up with its own proportions. */}
      <Table className="table-fixed">
        <TableHeader>
          <TableRow className="bg-muted/40 hover:bg-muted/40">
            {columns.map((column) => (
              <TableHead
                className={cn(
                  "h-11 px-4 text-xs font-medium text-muted-foreground",
                  column.width,
                )}
                key={column.header}
              >
                {column.header}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((row) => (
            <TableRow key={row.key}>
              {row.cells.map((cell, index) => (
                <TableCell
                  /* `whitespace-normal` undoes the primitive's nowrap, which
                     is right for a data row and wrong here — it lets prose
                     push a column past the width declared for it. */
                  className="px-4 py-3.5 align-top whitespace-normal"
                  key={columns[index]?.header ?? index}
                >
                  {cell}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}

/**
 * A name in the column that names things — but only when the name is something
 * you type: a token, a class, a variant, a component. Mono is what says "this
 * is a literal", so spending it on an English word spends it for nothing.
 */
export function ReferenceName({ children }: { children: React.ReactNode }) {
  return <span className="font-mono text-sm">{children}</span>
}

/** The same column when the name is a word rather than a literal. */
export function ReferenceLabel({ children }: { children: React.ReactNode }) {
  return <span className="text-sm font-medium">{children}</span>
}

/** The prose column. Muted, because the name and the specimen lead. */
export function ReferenceNote({ children }: { children: React.ReactNode }) {
  return (
    <span className="text-sm leading-relaxed text-muted-foreground">
      {children}
    </span>
  )
}

"use client"

import * as React from "react"

import {
  CostIcon,
  ModelIcon,
  TranscriptIcon,
} from "@/components/design-system/icons"
import {
  ReferenceLabel,
  ReferenceName,
  ReferenceNote,
  ReferenceTable,
  type ReferenceRow,
} from "@/components/design-system/reference-table"
import { Separator } from "@/components/ui/separator"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"

/**
 * Tabs, and the three things that get mistaken for them.
 *
 * The rule is one object seen several ways. Everything that goes wrong with
 * tabs is a different relationship wearing them: steps are a sequence and the
 * reader cannot skip one, separate objects are separate routes and need their
 * own URL, and a single setting is a drawer beside the thing it belongs to.
 * All three are patterns on this tab already, which is why the alternatives
 * name them rather than describing them.
 *
 * Two weights, sharing one selection so that clicking either moves both —
 * they are one component, and a preview that let them drift would imply two.
 */

const VIEWS = [
  { id: "transcript", label: "Transcript", Icon: TranscriptIcon },
  { id: "model", label: "Model", Icon: ModelIcon },
  { id: "cost", label: "Cost", Icon: CostIcon },
]

/**
 * What each tab shows: one call, seen three ways.
 *
 * The three panels are deliberately different tables rather than the same one
 * with different numbers in it — the rule this topic teaches is that tabs hold
 * views of one object, and three views that look identical demonstrate nothing.
 * The amounts add up to the $0.41 CL-8842 carries on the index page, because a
 * reader who checks is a reader the mock data should not lose.
 */
const PANELS: Record<
  string,
  { columns: { header: string; width?: string }[]; rows: ReferenceRow[] }
> = {
  transcript: {
    columns: [
      { header: "Speaker", width: "w-32" },
      { header: "At", width: "w-20" },
      { header: "Line" },
    ],
    rows: [
      {
        key: "t1",
        cells: [
          <ReferenceLabel key="s">Agent</ReferenceLabel>,
          <ReferenceNote key="a">0:00</ReferenceNote>,
          <ReferenceNote key="l">
            Rawabi Holding, how can I help?
          </ReferenceNote>,
        ],
      },
      {
        key: "t2",
        cells: [
          <ReferenceLabel key="s">Customer</ReferenceLabel>,
          <ReferenceNote key="a">0:04</ReferenceNote>,
          <ReferenceNote key="l">
            I need to move my delivery to Thursday.
          </ReferenceNote>,
        ],
      },
      {
        key: "t3",
        cells: [
          <ReferenceLabel key="s">Agent</ReferenceLabel>,
          <ReferenceNote key="a">0:09</ReferenceNote>,
          <ReferenceNote key="l">
            I can do that. Can I take the order number?
          </ReferenceNote>,
        ],
      },
    ],
  },
  model: {
    columns: [{ header: "Setting", width: "w-56" }, { header: "Value" }],
    rows: [
      {
        key: "m1",
        cells: [
          <ReferenceLabel key="s">Model</ReferenceLabel>,
          <ReferenceName key="v">gpt-4o-mini</ReferenceName>,
        ],
      },
      {
        key: "m2",
        cells: [
          <ReferenceLabel key="s">Voice</ReferenceLabel>,
          <ReferenceNote key="v">Layla — Gulf Arabic</ReferenceNote>,
        ],
      },
      {
        key: "m3",
        cells: [
          <ReferenceLabel key="s">Temperature</ReferenceLabel>,
          <ReferenceName key="v">0.3</ReferenceName>,
        ],
      },
      {
        key: "m4",
        cells: [
          <ReferenceLabel key="s">Turn limit</ReferenceLabel>,
          <ReferenceName key="v">24</ReferenceName>,
        ],
      },
    ],
  },
  cost: {
    columns: [{ header: "Item", width: "w-56" }, { header: "Amount" }],
    rows: [
      {
        key: "c1",
        cells: [
          <ReferenceLabel key="i">Speech to text</ReferenceLabel>,
          <ReferenceNote key="a">$0.03</ReferenceNote>,
        ],
      },
      {
        key: "c2",
        cells: [
          <ReferenceLabel key="i">Model</ReferenceLabel>,
          <ReferenceNote key="a">$0.11</ReferenceNote>,
        ],
      },
      {
        key: "c3",
        cells: [
          <ReferenceLabel key="i">Text to speech</ReferenceLabel>,
          <ReferenceNote key="a">$0.06</ReferenceNote>,
        ],
      },
      {
        key: "c4",
        cells: [
          <ReferenceLabel key="i">Telephony</ReferenceLabel>,
          <ReferenceNote key="a">$0.21</ReferenceNote>,
        ],
      },
      {
        key: "c5",
        cells: [
          <ReferenceLabel key="i">Total</ReferenceLabel>,
          <ReferenceLabel key="a">$0.41</ReferenceLabel>,
        ],
      },
    ],
  },
}

const INSTEAD = [
  {
    when: "Several views of one object",
    surface: "Tabs",
    why: "The object does not change as the reader moves between them.",
  },
  {
    when: "Steps toward making one object",
    surface: "Multi-step creation",
    why: "A sequence. The reader cannot skip one, and tabs imply they can.",
  },
  {
    when: "A different object",
    surface: "A route of its own",
    why: "It needs a URL someone can send. A tab has no address.",
  },
  {
    when: "One setting on the object",
    surface: "Drawer",
    why: "You still need the page behind it while you change it.",
  },
]

/** Where the moving marker sits, in the list's own pixels. */
type Marker = { base: number; x: number; scale: number }

/**
 * The travel, measured rather than guessed.
 *
 * The tabs are as wide as their words, so the marker has to change width as
 * well as move — and width is a layout property. It is drawn at the width of
 * the widest tab and scaled down from its left edge instead, which is a
 * transform, so the whole move is one composited property.
 */
function useMarker(active: string) {
  const triggers = React.useRef(new Map<string, HTMLButtonElement>())
  const [marker, setMarker] = React.useState<Marker | null>(null)

  React.useEffect(() => {
    const measure = () => {
      const nodes = Array.from(triggers.current.values())
      const current = triggers.current.get(active)
      if (!current || !nodes.length) return
      const base = Math.max(...nodes.map((node) => node.offsetWidth))
      setMarker({
        base,
        x: current.offsetLeft,
        scale: current.offsetWidth / base,
      })
    }

    measure()

    /* Every label changes width when Nunito finishes loading, and again at a
       narrower viewport, so the marker is re-measured rather than measured
       once. */
    const observer = new ResizeObserver(measure)
    for (const node of triggers.current.values()) observer.observe(node)
    return () => observer.disconnect()
  }, [active])

  return { triggers, marker }
}

/** Collects the trigger nodes the measurement above reads. */
function triggerRef(
  triggers: React.RefObject<Map<string, HTMLButtonElement>>,
  id: string,
) {
  return (node: HTMLButtonElement | null) => {
    if (node) triggers.current.set(id, node)
    else triggers.current.delete(id)
  }
}

export function TabsPreview() {
  const [view, setView] = React.useState(VIEWS[0].id)

  return (
    <div className="flex flex-col gap-8">
      <div className="flex flex-col gap-4">
        <span className="text-sm font-medium">Primary</span>
        <PrimaryTabs onValueChange={setView} value={view} />
      </div>

      <div className="flex flex-col gap-4">
        <span className="text-sm font-medium">Secondary</span>
        <SecondaryTabs onValueChange={setView} value={view}>
          {/* The same arrival the docs pane uses, and deliberately the same
              token: a tab panel and a topic pane are one event at two scales,
              and two near-identical curves is how a system stops having one.

              Scoped to the active state, not put on the element. Radix keeps
              all three panels mounted and hides the inactive ones with the
              `hidden` attribute, so the element is never rebuilt and a plain
              `animate-pane-in` played once on first mount and never again.
              Attached to `data-active` it is added and removed with the state,
              which is what restarts it on every switch.

              Nothing animates out: the panel leaving is hidden outright, so
              there is nothing to fade and nothing to position absolutely.

              motion-safe as well as motion-reduce, because a bare
              `motion-reduce:animate-none` lost here: it is one class deep and
              `data-active:animate-pane-in` is a class plus an attribute, so
              the animation outranked its own escape and still played under
              reduced motion. Gating the animation on motion-safe means there
              is nothing to outrank — under reduce the class never applies. */}
          {VIEWS.map((entry) => (
            <TabsContent
              className="motion-safe:data-active:animate-pane-in motion-reduce:animate-none"
              key={entry.id}
              value={entry.id}
            >
              <ReferenceTable
                columns={PANELS[entry.id].columns}
                rows={PANELS[entry.id].rows}
              />
            </TabsContent>
          ))}
        </SecondaryTabs>
      </div>

      {/* The rule below is documentation about tabs, not a view of the call
          above it. Without this line it sits where a panel sits and reads as
          one — which is what it did before the panels existed. */}
      <Separator />

      <ReferenceTable
        columns={[
          { header: "What you have", width: "w-72" },
          { header: "Reach for", width: "w-56" },
          { header: "Why" },
        ]}
        rows={INSTEAD.map((one) => ({
          key: one.when,
          cells: [
            <ReferenceLabel key="w">{one.when}</ReferenceLabel>,
            <ReferenceLabel key="s">{one.surface}</ReferenceLabel>,
            <ReferenceNote key="y">{one.why}</ReferenceNote>,
          ],
        }))}
      />
    </div>
  )
}

/**
 * The page's own tabs: the view you are on is a filled tab.
 *
 * No track behind the row — three labels and one filled tab say which view
 * you are on, and a grey trough around them says nothing a reader needs. What
 * the trough did carry is that the three belong together, so a rule under the
 * row carries it instead, as wide as the tabs and no wider, which is the
 * difference between a tab bar and three buttons someone left in a line.
 *
 * Geometry goes in `style` because it is measured; every class here is on the
 * scale.
 */
export type TabItem = {
  id: string
  label: string
  Icon?: React.ComponentType
}

export function PrimaryTabs({
  items = VIEWS,
  onValueChange,
  value,
  children,
}: {
  /** The views. Defaults to this topic's own three. */
  items?: TabItem[]
  onValueChange: (value: string) => void
  value: string
  /** The panels, as `TabsContent`. */
  children?: React.ReactNode
}) {
  const { triggers, marker } = useMarker(value)

  return (
    <Tabs className="gap-4" onValueChange={onValueChange} value={value}>
      <div className="flex w-fit flex-col gap-2">
        <TabsList className="relative gap-1 bg-transparent p-0">
          {marker ? (
            <div
              aria-hidden
              className="absolute inset-y-0 left-0 origin-left rounded-lg bg-muted transition-transform duration-200 ease-out-cubic motion-reduce:transition-none"
              style={{
                width: marker.base,
                transform: `translateX(${marker.x}px) scaleX(${marker.scale})`,
              }}
            />
          ) : null}
          {items.map((entry) => (
            /* The pill behind is the only background drawn, so the trigger's
               own active background would sit on top of it and hide the
               travel, and its active shadow would be cast by a box with
               nothing in it. The shadow is switched off under the primitive's
               own variant prefix so the two classes merge; a bare
               `data-active:shadow-none` loses to it on specificity and the
               shadow survives.

               Hover is lighter than the pill on purpose. It only has to say
               the tab is a control; at the pill's own weight a hovered tab and
               the open one look identical, and the row reads as two open tabs
               for as long as the pointer sits there. */
            <TabsTrigger
              className="flex-none gap-2 px-3 data-active:bg-transparent not-data-active:hover:bg-muted/60 group-data-[variant=default]/tabs-list:data-active:shadow-none"
              key={entry.id}
              ref={triggerRef(triggers, entry.id)}
              value={entry.id}
            >
              {entry.Icon ? <entry.Icon /> : null}
              {entry.label}
            </TabsTrigger>
          ))}
        </TabsList>
        <Separator />
      </div>

      {children}
    </Tabs>
  )
}

/**
 * The lighter weight: a rule under the words, and the selected word carries a
 * segment of it.
 *
 * For views inside a page that already has a tab bar — a section of a drawer,
 * a panel within a view — where a second row of filled tabs would compete
 * with the first for which one is the page.
 *
 * The primitive's `line` variant already draws an underline, but it draws one
 * per trigger and fades between them, so nothing connects the tab you left to
 * the tab you arrived at. One bar that travels does, and it is the same
 * measured move as the pill above. The per-trigger underline is switched off
 * under the primitive's own variant prefix so the two classes merge, the same
 * reason the shadow is.
 */
export function SecondaryTabs({
  items = VIEWS,
  aside,
  children,
  onValueChange,
  value,
}: {
  /** The views. Defaults to this topic's own three. */
  items?: TabItem[]
  /** Sits at the end of the tab row — a control that scopes every tab,
   *  such as what a diff is compared with. */
  aside?: React.ReactNode
  children: React.ReactNode
  onValueChange: (value: string) => void
  value: string
}) {
  const { triggers, marker } = useMarker(value)

  return (
    <Tabs className="gap-4" onValueChange={onValueChange} value={value}>
      <div className="flex items-center justify-between gap-4">
        {/* No gap above the rule: the trigger's own height already leaves
            room under the words, and a gap on top of it floated the bar
            away from the label it belongs to. */}
        <div className="relative flex w-fit flex-col">
          <TabsList className="gap-1 p-0" variant="line">
            {items.map((entry) => (
              <TabsTrigger
                className="flex-none gap-2 px-3 group-data-[variant=line]/tabs-list:data-active:after:opacity-0"
                key={entry.id}
                ref={triggerRef(triggers, entry.id)}
                value={entry.id}
              >
                {entry.Icon ? <entry.Icon /> : null}
                {entry.label}
              </TabsTrigger>
            ))}
          </TabsList>
          <Separator />

          {/* Sits on the rule rather than under it: the bar is the part of the
              rule the open tab owns, not a second line below it. */}
          {marker ? (
            <div
              aria-hidden
              className="absolute bottom-0 left-0 h-0.5 origin-left rounded-full bg-primary transition-transform duration-200 ease-out-cubic motion-reduce:transition-none"
              style={{
                width: marker.base,
                transform: `translateX(${marker.x}px) scaleX(${marker.scale})`,
              }}
            />
          ) : null}
        </div>
        {aside}
      </div>

      {children}
    </Tabs>
  )
}

