  )
}

"use client"

import * as React from "react"
import { Cancel01Icon, PlusSignIcon } from "@hugeicons/core-free-icons"
import type { DateRange } from "react-day-picker"

import { Button } from "@/components/ui/button"
import { ButtonGroup } from "@/components/ui/button-group"
import { Calendar } from "@/components/ui/calendar"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Field, FieldLabel } from "@/components/ui/field"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
  InputGroupText,
} from "@/components/ui/input-group"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Separator } from "@/components/ui/separator"
import { icon } from "@/components/shared/icon"

const AddIcon = icon(PlusSignIcon, "AddIcon")
const ClearIcon = icon(Cancel01Icon, "ClearIcon")

export type { DateRange }
export type FilterOption = { value: string; label: string }
export type Range = { min?: number; max?: number }

/**
 * Filters as a row of chips under the search.
 *
 * A filter that is not set is one small chip naming its field — "+ Language" —
 * so ten of them cost a line, not a toolbar. Opening one gives its control the
 * room it needs (a checklist, a calendar) in a popover. Once set, the chip
 * reads its value and grows an × to clear it. Past two set filters the row
 * ends in Clear all.
 *
 * Show the three or four filters people reach for as chips; put the rest
 * behind AddFilter, which turns a chosen field into a chip of its own.
 */
export function FilterBar({
  children,
  activeCount = 0,
  onClearAll,
}: {
  children: React.ReactNode
  /** How many filters are set. Clear all appears at two. */
  activeCount?: number
  onClearAll?: () => void
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      {children}
      {activeCount >= 2 ? (
        <Button variant="ghost" size="xs" onClick={onClearAll}>
          Clear all
        </Button>
      ) : null}
    </div>
  )
}

/**
 * The chip itself: "+ Field" when empty, "Field: value" and an × once set.
 * One tree for both states: swapping the button for a group once a value is
 * set would remount the trigger, and the open list would close on the first
 * tick.
 */
function Chip({
  field,
  summary,
  onClear,
  trigger,
}: {
  field: string
  /** What the filter is set to, or null when it is not set. */
  summary: string | null
  onClear: () => void
  trigger: (button: React.ReactElement) => React.ReactNode
}) {
  return (
    <ButtonGroup>
      {trigger(
        <Button variant="outline" size="xs">
          {summary ? (
            <>
              {field}: <span className="font-semibold">{summary}</span>
            </>
          ) : (
            <>
              <AddIcon />
              {field}
            </>
          )}
        </Button>,
      )}
      {summary ? (
        <Button
          variant="outline"
          size="icon-xs"
          aria-label={`Clear ${field}`}
          onClick={onClear}
        >
          <ClearIcon />
        </Button>
      ) : null}
    </ButtonGroup>
  )
}

/* ---------------------------------------------------------------- summaries */

/**
 * What a many-value filter reads once set: the value, two values when both
 * fit, and past that the first value and how many more — "Completed +2".
 * A bare count ("Status: 3") makes you open the chip to learn anything.
 */
function manySummary(options: FilterOption[], value: string[]) {
  if (!value.length) return null
  const labels = value.map(
    (item) => options.find((option) => option.value === item)?.label ?? item,
  )
  if (labels.length === 1) return labels[0]
  if (labels.length === 2 && labels.join(", ").length <= 24)
    return labels.join(", ")
  return `${labels[0]} +${labels.length - 1}`
}

const DAY = 24 * 60 * 60 * 1000

function datePresets(today: Date) {
  return [
    { label: "Today", from: today },
    { label: "Last 7 days", from: new Date(today.getTime() - 6 * DAY) },
    { label: "Last 30 days", from: new Date(today.getTime() - 29 * DAY) },
  ]
}

function dateSummary(value: DateRange | undefined, today: Date) {
  if (!value?.from) return null
  const preset = datePresets(today).find(
    (entry) =>
      value.from?.toDateString() === entry.from.toDateString() &&
      value.to?.toDateString() === today.toDateString(),
  )
  return (
    preset?.label ??
    [value.from, value.to]
      .filter(Boolean)
      .map((date) =>
        date!.toLocaleDateString("en-GB", { day: "numeric", month: "short" }),
      )
      .join(" – ")
  )
}

function rangeSummary(range: Range | null, unit: string) {
  if (!range) return null
  const { min, max } = range
  if (min !== undefined && max !== undefined) return `${min}–${max} ${unit}`
  if (min !== undefined) return `Over ${min} ${unit}`
  if (max !== undefined) return `Under ${max} ${unit}`
  return null
}

/** Past this many options the list gets a search box. */
const SEARCH_FROM = 8

/**
 * The one list every select filter opens, many-value or one-value, so the two
 * cannot drift apart: same rows, the tick on the right. A short list is the
 * standard dropdown menu, so it looks like every other dropdown in the
 * product; a long one needs a search box, so it is a command list. A set
 * many-value list ends in Clear.
 */
function OptionList({
  button,
  field,
  options,
  selected,
  onSelect,
  onClear,
  closeOnSelect,
}: {
  button: React.ReactElement
  field: string
  options: FilterOption[]
  selected: string[]
  onSelect: (value: string) => void
  onClear?: () => void
  /** One-value filters close on a pick; many-value ones stay open. */
  closeOnSelect: boolean
}) {
  const [open, setOpen] = React.useState(false)
  /* Ticked ones float to the top of a long list, so they are never scrolled
     out of sight — but only when it opens, not under the pointer. */
  const [order, setOrder] = React.useState(options)

  if (options.length < SEARCH_FROM) {
    return (
      <DropdownMenu modal={false} open={open} onOpenChange={setOpen}>
        <DropdownMenuTrigger asChild>{button}</DropdownMenuTrigger>
        <DropdownMenuContent
          align="start"
          className="w-auto min-w-(--radix-dropdown-menu-trigger-width)"
        >
          {options.map((option) => (
            <DropdownMenuCheckboxItem
              checked={selected.includes(option.value)}
              key={option.value}
              onSelect={(event) => {
                /* A many-value list stays open while ticking. */
                if (!closeOnSelect) event.preventDefault()
                onSelect(option.value)
              }}
            >
              {option.label}
            </DropdownMenuCheckboxItem>
          ))}
          {onClear && selected.length ? (
            <>
              <DropdownMenuSeparator />
              <DropdownMenuItem onSelect={onClear}>Clear</DropdownMenuItem>
            </>
          ) : null}
        </DropdownMenuContent>
      </DropdownMenu>
    )
  }

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        if (next && options.length >= SEARCH_FROM)
          setOrder([
            ...options.filter((o) => selected.includes(o.value)),
            ...options.filter((o) => !selected.includes(o.value)),
          ])
        setOpen(next)
      }}
    >
      <PopoverTrigger asChild>{button}</PopoverTrigger>
      <PopoverContent align="start" className="w-64 p-0">
        <Command>
          {options.length >= SEARCH_FROM ? (
            <CommandInput placeholder={`Search ${field.toLowerCase()}`} />
          ) : null}
          <CommandList>
            <CommandEmpty>No match</CommandEmpty>
            <CommandGroup>
              {(options.length >= SEARCH_FROM ? order : options).map(
                (option) => (
                  <CommandItem
                    className="truncate"
                    data-checked={selected.includes(option.value)}
                    key={option.value}
                    onSelect={() => {
                      onSelect(option.value)
                      if (closeOnSelect) setOpen(false)
                    }}
                    value={option.label}
                  >
                    {option.label}
                  </CommandItem>
                ),
              )}
            </CommandGroup>
          </CommandList>
          {onClear && selected.length ? (
            <div className="border-t p-1">
              <Button
                className="w-full"
                onClick={onClear}
                size="sm"
                variant="ghost"
              >
                Clear
              </Button>
            </div>
          ) : null}
        </Command>
      </PopoverContent>
    </Popover>
  )
}

/** Pick one or more values. The list stays open while ticking. */
export function SelectFilter({
  field,
  options,
  value,
  onChange,
}: {
  field: string
  options: FilterOption[]
  value: string[]
  onChange: (value: string[]) => void
}) {
  return (
    <Chip
      field={field}
      summary={manySummary(options, value)}
      onClear={() => onChange([])}
      trigger={(button) => (
        <OptionList
          button={button}
          closeOnSelect={false}
          field={field}
          onClear={() => onChange([])}
          onSelect={(item) =>
            onChange(
              value.includes(item)
                ? value.filter((entry) => entry !== item)
                : [...value, item],
            )
          }
          options={options}
          selected={value}
        />
      )}
    />
  )
}

/** Pick exactly one value — a direction, a channel. Choosing closes it. */
export function ChoiceFilter({
  field,
  options,
  value,
  onChange,
}: {
  field: string
  options: FilterOption[]
  value: string | null
  onChange: (value: string | null) => void
}) {
  return (
    <Chip
      field={field}
      summary={options.find((option) => option.value === value)?.label ?? null}
      onClear={() => onChange(null)}
      trigger={(button) => (
        <OptionList
          button={button}
          closeOnSelect
          field={field}
          onSelect={(item) => onChange(item === value ? null : item)}
          options={options}
          selected={value ? [value] : []}
        />
      )}
    />
  )
}

/** A date range: presets first, then any range on the calendar. */
export function DateFilter({
  field,
  value,
  onChange,
  today,
}: {
  field: string
  value: DateRange | undefined
  onChange: (value: DateRange | undefined) => void
  /** What "today" is. Mock data is dated, so the demo fixes it. */
  today: Date
}) {
  return (
    <Chip
      field={field}
      summary={dateSummary(value, today)}
      onClear={() => onChange(undefined)}
      trigger={(button) => (
        <Popover>
          <PopoverTrigger asChild>{button}</PopoverTrigger>
          <PopoverContent align="start" className="w-auto">
            <div className="flex gap-2">
              <div className="flex flex-col gap-1">
                {datePresets(today).map((entry) => (
                  <Button
                    key={entry.label}
                    variant={
                      dateSummary(value, today) === entry.label
                        ? "secondary"
                        : "ghost"
                    }
                    size="sm"
                    className="justify-start"
                    onClick={() => onChange({ from: entry.from, to: today })}
                  >
                    {entry.label}
                  </Button>
                ))}
              </div>
              <Separator orientation="vertical" />
              <Calendar
                mode="range"
                selected={value}
                onSelect={onChange}
                defaultMonth={value?.from ?? today}
                disabled={{ after: today }}
              />
            </div>
          </PopoverContent>
        </Popover>
      )}
    />
  )
}

/**
 * A number between two bounds — duration, cost. The common bands are one
 * click; Min and Max take anything else, and either may be left empty.
 */
export function RangeFilter({
  field,
  unit,
  presets,
  value,
  onChange,
}: {
  field: string
  unit: string
  presets: Range[]
  value: Range | null
  onChange: (value: Range | null) => void
}) {
  const id = React.useId()
  const set = (next: Range) =>
    onChange(next.min === undefined && next.max === undefined ? null : next)
  const read = (raw: string) => (raw === "" ? undefined : Number(raw))
  const current = value ?? {}

  return (
    <Chip
      field={field}
      summary={rangeSummary(value, unit)}
      onClear={() => onChange(null)}
      trigger={(button) => (
        <Popover>
          <PopoverTrigger asChild>{button}</PopoverTrigger>
          <PopoverContent align="start" className="flex w-64 flex-col gap-3">
            <div className="flex flex-col gap-1">
              {presets.map((preset) => {
                const label = rangeSummary(preset, unit)!
                const on =
                  preset.min === value?.min && preset.max === value?.max
                return (
                  <Button
                    className="justify-start"
                    key={label}
                    onClick={() => set(preset)}
                    size="sm"
                    variant={on ? "secondary" : "ghost"}
                  >
                    {label}
                  </Button>
                )
              })}
            </div>
            <Separator />
            <div className="grid grid-cols-2 gap-2">
              {(["min", "max"] as const).map((bound) => (
                <Field key={bound}>
                  <FieldLabel htmlFor={`${id}-${bound}`}>
                    {bound === "min" ? "Min" : "Max"}
                  </FieldLabel>
                  <InputGroup>
                    <InputGroupInput
                      id={`${id}-${bound}`}
                      inputMode="numeric"
                      onChange={(event) =>
                        set({ ...current, [bound]: read(event.target.value) })
                      }
                      value={current[bound] ?? ""}
                    />
                    <InputGroupAddon align="inline-end">
                      <InputGroupText>{unit}</InputGroupText>
                    </InputGroupAddon>
                  </InputGroup>
                </Field>
              ))}
            </div>
          </PopoverContent>
        </Popover>
      )}
    />
  )
}

/**
 * A filter that is either on or off — "Scheduled only". Clicking the chip
 * turns it on; there is nothing to choose, so nothing opens.
 */
export function ToggleFilter({
  field,
  value,
  onChange,
}: {
  field: string
  value: boolean
  onChange: (value: boolean) => void
}) {
  return (
    <ButtonGroup>
      <Button onClick={() => onChange(!value)} size="xs" variant="outline">
        {value ? (
          <span className="font-semibold">{field}</span>
        ) : (
          <>
            <AddIcon />
            {field}
          </>
        )}
      </Button>
      {value ? (
        <Button
          aria-label={`Clear ${field}`}
          onClick={() => onChange(false)}
          size="icon-xs"
          variant="outline"
        >
          <ClearIcon />
        </Button>
      ) : null}
    </ButtonGroup>
  )
}

/** The filters not shown as chips. Choosing one adds its chip to the row. */
export function AddFilter({
  fields,
  onAdd,
}: {
  fields: { id: string; label: string }[]
  onAdd: (id: string) => void
}) {
  if (!fields.length) return null

  return (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" size="xs">
          <AddIcon />
          Filter
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start">
        {fields.map((field) => (
          <DropdownMenuItem key={field.id} onSelect={() => onAdd(field.id)}>
            {field.label}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

"use client"

import { useEffect, useRef } from "react"

import { TONES, type OrbTone } from "@/components/shared/orb-tones"
import { Avatar } from "@/components/ui/avatar"

/**
 * A disc of liquid light that stands in for someone with no photo.
 *
 * Drawn by a fragment shader: a soft two-blob gradient seen through a lattice
 * of diamond lenses, each one flipping the light behind it, with a bevel and a
 * groove between cells. The blobs drift, so the light rolls through the
 * lattice. The name sets the tone and where
 * the blobs start, so the same name always gets the same orb and a list of
 * them does not repeat one picture.
 *
 * One WebGL context for every avatar on the page. Browsers cap live contexts
 * at around sixteen, so a context per avatar breaks a list of forty. Instead
 * a single offscreen canvas draws each visible avatar in turn, every frame,
 * at that avatar's own pixel size, and copies the frame into the avatar's 2D
 * canvas. Off-screen avatars are skipped, and under reduced motion each one
 * is drawn once and left still.
 *
 * The colours are read from the live tokens, not written here, so the orbs
 * follow a brand or whitelabel change.
 */

type Rgb = [number, number, number]

/* How far toward white the body and the light sit, for a one-token tone. */
const BODY = 0.4
const LIGHT = 0.75

function toward(rgb: Rgb, amount: number): Rgb {
  return rgb.map((c) => c + (1 - c) * amount) as Rgb
}

function toneRgb(tone: OrbTone): Rgb[] {
  const stops: readonly string[] = TONES[tone]
  const [deep, body, light] = stops.map(classRgb)
  return [deep, body ?? toward(deep, BODY), light ?? toward(deep, LIGHT)]
}

const VERTEX = `
attribute vec2 p;
void main() { gl_Position = vec4(p, 0.0, 1.0); }
`

const FRAGMENT = `
precision highp float;
uniform vec2 uRes;
uniform float uSeed;
uniform float uTime;
uniform vec3 uA;
uniform vec3 uB;
uniform vec3 uC;

/* How many cells run across the disc: fine enough to read as a texture, and
   still about five device pixels a cell on a 24px avatar. */
const float CELLS = 9.0;

/* How strongly each cell flips and magnifies the light behind it. */
const float LENS = 0.6;

/* The light: one bright blob and one deep one, drifting on their own slow
   orbits. The seed sets where each starts, so every name is at a different
   point on the same loop. */
float field(vec2 p) {
  vec2 bright = vec2(cos(uSeed + uTime * 0.7), sin(uSeed * 1.3 + uTime * 0.5)) * 0.55;
  vec2 deep = vec2(cos(uSeed + 2.6 - uTime * 0.4), sin(uSeed * 0.7 + 2.6 + uTime * 0.6)) * 0.45;
  float f = 0.5
    + 0.7 * smoothstep(1.6, 0.0, length(p - bright))
    - 0.6 * smoothstep(1.2, 0.0, length(p - deep));
  return clamp(f, 0.0, 1.0);
}

vec3 ramp(float f) {
  vec3 col = mix(uA, uB, smoothstep(0.0, 0.55, f));
  return mix(col, uC, smoothstep(0.45, 1.0, f));
}

void main() {
  vec2 uv = (gl_FragCoord.xy * 2.0 - uRes) / uRes.y;
  float mask = 1.0 - smoothstep(1.0 - 4.0 / uRes.y, 1.0, length(uv));
  if (mask <= 0.0) {
    gl_FragColor = vec4(0.0);
    return;
  }

  /* A square grid turned 45 degrees, so the cells are diamonds and the
     lines between them run on the diagonals. */
  mat2 turn = mat2(0.7071, -0.7071, 0.7071, 0.7071);
  mat2 back = mat2(0.7071, 0.7071, -0.7071, 0.7071);
  vec2 g = turn * uv * CELLS * 0.5;
  vec2 cell = fract(g) - 0.5;

  /* Each cell is a lens: it shows the light behind its own centre, flipped
     and magnified, which is what makes the lattice read as liquid glass
     rather than a pattern printed on top. */
  vec2 offset = back * cell * (2.0 / CELLS);
  float f = field(uv - offset * (1.0 + LENS));
  vec3 col = ramp(f);

  /* The bevel: each diamond catches light on its upper-left faces and falls
     into shade on the lower-right, strongest at the rim. */
  float d = max(abs(cell.x), abs(cell.y));
  vec2 face = back * (abs(cell.x) > abs(cell.y) ? vec2(sign(cell.x), 0.0) : vec2(0.0, sign(cell.y)));
  float lit = dot(face, vec2(-0.7071, 0.7071));
  col += smoothstep(0.2, 0.5, d) * lit * 0.08;

  /* The groove between cells, drawn a step deeper on the ramp than the
     light it runs through, so it shows on the pale side and sinks on the
     deep side the way a real channel would. */
  float aa = 1.5 * CELLS / uRes.y;
  float groove = smoothstep(0.5 - 2.5 * aa, 0.5, d);
  col = mix(col, ramp(f * 0.7), groove * 0.55);

  gl_FragColor = vec4(col * mask, mask);
}
`

type Renderer = {
  gl: WebGLRenderingContext
  uniforms: Record<
    "res" | "seed" | "time" | "a" | "b" | "c",
    WebGLUniformLocation | null
  >
}

let renderer: Renderer | null | undefined

function compile(gl: WebGLRenderingContext, type: number, source: string) {
  const shader = gl.createShader(type)
  if (!shader) return null
  gl.shaderSource(shader, source)
  gl.compileShader(shader)
  return gl.getShaderParameter(shader, gl.COMPILE_STATUS) ? shader : null
}

function getRenderer(): Renderer | null {
  if (renderer !== undefined) return renderer
  renderer = null

  const gl = document.createElement("canvas").getContext("webgl", {
    premultipliedAlpha: true,
  })
  if (!gl) return null

  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX)
  const fragment = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT)
  const program = gl.createProgram()
  if (!vertex || !fragment || !program) return null
  gl.attachShader(program, vertex)
  gl.attachShader(program, fragment)
  gl.linkProgram(program)
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null
  gl.useProgram(program)

  /* One triangle that covers the whole viewport. */
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer())
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 3, -1, -1, 3]),
    gl.STATIC_DRAW,
  )
  const position = gl.getAttribLocation(program, "p")
  gl.enableVertexAttribArray(position)
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0)

  renderer = {
    gl,
    uniforms: {
      res: gl.getUniformLocation(program, "uRes"),
      seed: gl.getUniformLocation(program, "uSeed"),
      time: gl.getUniformLocation(program, "uTime"),
      a: gl.getUniformLocation(program, "uA"),
      b: gl.getUniformLocation(program, "uB"),
      c: gl.getUniformLocation(program, "uC"),
    },
  }
  return renderer
}

/* A colour class as 0–1 RGB. A hidden element wearing the class gives the
   resolved colour, which may be oklch or lab, and a 2D canvas turns any CSS
   colour into sRGB pixels. */
let probe: CanvasRenderingContext2D | null = null

function classRgb(className: string): Rgb {
  probe ??= document
    .createElement("canvas")
    .getContext("2d", { willReadFrequently: true })
  if (!probe) return [0.5, 0.5, 0.5]

  const swatch = document.createElement("span")
  swatch.className = `${className} hidden`
  document.body.append(swatch)
  const value = getComputedStyle(swatch).backgroundColor
  swatch.remove()

  probe.clearRect(0, 0, 1, 1)
  probe.fillStyle = value
  probe.fillRect(0, 0, 1, 1)
  const [r, g, b] = probe.getImageData(0, 0, 1, 1).data
  return [r / 255, g / 255, b / 255]
}

function hash(value: string) {
  let h = 2166136261
  for (const char of value)
    h = Math.imul(h ^ char.charCodeAt(0), 16777619) >>> 0
  return h
}

type Orb = {
  canvas: HTMLCanvasElement
  context: CanvasRenderingContext2D
  seed: number
  colours: [number, number, number][]
  visible: boolean
}

const orbs = new Set<Orb>()
let frame = 0
const start = typeof performance === "undefined" ? 0 : performance.now()

/* Seconds of drift per real second. Slow: an avatar sits beside text someone
   is reading, and it should never pull the eye off it. */
const SPEED = 0.35

function paint(orb: Orb, time: number) {
  const r = getRenderer()
  if (!r) return
  const { gl, uniforms } = r
  const { width, height } = orb.canvas
  if (!width || !height) return

  const glCanvas = gl.canvas as HTMLCanvasElement
  if (glCanvas.width < width || glCanvas.height < height) {
    glCanvas.width = Math.max(glCanvas.width, width)
    glCanvas.height = Math.max(glCanvas.height, height)
  }

  gl.viewport(0, 0, width, height)
  gl.clearColor(0, 0, 0, 0)
  gl.clear(gl.COLOR_BUFFER_BIT)
  gl.uniform2f(uniforms.res, width, height)
  gl.uniform1f(uniforms.seed, orb.seed)
  gl.uniform1f(uniforms.time, time)
  gl.uniform3fv(uniforms.a, orb.colours[0])
  gl.uniform3fv(uniforms.b, orb.colours[1])
  gl.uniform3fv(uniforms.c, orb.colours[2])
  gl.drawArrays(gl.TRIANGLES, 0, 3)

  /* The viewport sits at the bottom of the GL canvas, which may be taller
     than this avatar, so copy from that corner. */
  orb.context.clearRect(0, 0, width, height)
  orb.context.drawImage(
    glCanvas,
    0,
    glCanvas.height - height,
    width,
    height,
    0,
    0,
    width,
    height,
  )
}

function tick(now: number) {
  const time = ((now - start) / 1000) * SPEED
  for (const orb of orbs) if (orb.visible) paint(orb, time)
  frame = orbs.size ? requestAnimationFrame(tick) : 0
}

export type OrbAvatarProps = React.ComponentProps<typeof Avatar> & {
  /** Who it stands for. Read out to screen readers and used as the seed. */
  name: string
  tone?: OrbTone
}

export function OrbAvatar({
  name,
  tone = "violet",
  children,
  ...props
}: OrbAvatarProps) {
  const ref = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    const canvas = ref.current
    const context = canvas?.getContext("2d")
    if (!canvas || !context) return

    /* Drawn at the avatar's real size in device pixels — no bigger, so a
       24px avatar costs a 48px draw on a retina screen. */
    const ratio = window.devicePixelRatio || 1
    canvas.width = Math.round(canvas.clientWidth * ratio)
    canvas.height = Math.round(canvas.clientHeight * ratio)

    const h = hash(name)
    const orb: Orb = {
      canvas,
      context,
      seed: ((h >>> 4) % 997) / 7,
      colours: toneRgb(tone),
      visible: true,
    }

    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      paint(orb, 0)
      return
    }

    const observer = new IntersectionObserver(([entry]) => {
      orb.visible = entry.isIntersecting
    })
    observer.observe(canvas)

    orbs.add(orb)
    frame ||= requestAnimationFrame(tick)

    return () => {
      observer.disconnect()
      orbs.delete(orb)
      if (!orbs.size) {
        cancelAnimationFrame(frame)
        frame = 0
      }
    }
  }, [name, tone])

  return (
    <Avatar {...props}>
      <canvas
        aria-label={name}
        className="size-full rounded-full"
        ref={ref}
        role="img"
      />
      {/* An AvatarBadge, as on any shadcn avatar. */}
      {children}
    </Avatar>
  )
}

"use client"

import * as React from "react"

import { Item } from "@/components/ui/item"

/**
 * The top of a page, one shape everywhere.
 *
 * Title on the left, with one line of description under it only when the
 * title does not say enough on its own. Whatever describes the page's state —
 * a quota, a sync status — sits on the right, level with the title. The ways
 * of adding to the page come after, as a row of tiles directly under the
 * title, so the reader meets the actions before the list they fill.
 *
 * The layout follows ElevenLabs' knowledge base page; the look is ours.
 */
export function PageHeader({
  title,
  description,
  aside,
  actions,
}: {
  title: React.ReactNode
  /** Optional. Leave it out when the title already says what the page is. */
  description?: React.ReactNode
  /** Page state, shown on the right of the title — never an action. */
  aside?: React.ReactNode
  /** `ActionTile`s. A page with nothing to add has none. */
  actions?: React.ReactNode
}) {
  return (
    <header className="flex flex-col gap-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="flex flex-col gap-1">
          <h1 className="text-2xl font-semibold">{title}</h1>
          {description ? (
            <p className="text-sm text-muted-foreground">{description}</p>
          ) : null}
        </div>
        {aside}
      </div>

      {actions ? <div className="flex flex-wrap gap-3">{actions}</div> : null}
    </header>
  )
}

/**
 * One way of adding to the page: an icon over a label, nothing else. The
 * label carries the verb, so there is no second line explaining it — what a
 * choice accepts is said in the dialog it opens.
 */
export function ActionTile({
  icon,
  label,
  onClick,
}: {
  icon: React.ReactNode
  label: string
  onClick?: () => void
}) {
  return (
    <Item
      variant="outline"
      asChild
      /* On the Item, not the button: Slot joins the two class lists without
         merging them, so the Item's own w-full and padding would win. */
      className="w-36 flex-col items-start gap-2 p-3 [&_svg]:size-4 text-start transition-colors duration-150 ease-out-cubic hover:bg-muted motion-reduce:transition-none"
    >
      <button type="button" onClick={onClick}>
        {icon}
        <span className="font-medium">{label}</span>
      </button>
    </Item>
  )
}

