                )}
              </BreadcrumbItem>
            </React.Fragment>
          ))}
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex shrink-0 items-center gap-2">
        {scope}
        {actions ?? (
          <>
            {developers ? (
              <Button
                aria-current={developers === "open" ? "page" : undefined}
                size="sm"
                variant={developers === "open" ? "secondary" : "outline"}
              >
                <DeveloperDocsIcon />
                Developers
              </Button>
            ) : (
              <Button size="sm" variant="outline">
                <DeveloperDocsIcon />
                Developer Doc
              </Button>
            )}
            {/* The same allowlist the nav reads. The app has this gear on its own
            check today, which is how an admin gets a second dead end to the
            page the sidebar already sent them to. */}
            {showSettings ? (
              <Button
                aria-label="Global settings"
                size="icon-sm"
                variant="outline"
              >
                <SettingsIcon />
              </Button>
            ) : null}
            {/* Wrapped, rather than given `self-center`: the primitive ships
            `data-vertical:self-stretch`, and an attribute variant outranks a
            plain utility, so the rule stretched to the 28px row, got held to
            h-4, and settled at the top of it — 6px above the centre the buttons
            and the avatar share. Inside a wrapper of its own the flex line is
            the rule's own height, so stretching changes nothing and the wrapper
            is what the header centres. */}
            <div className="flex items-center">
              <Separator className="mx-1 h-4" orientation="vertical" />
            </div>
            {/* A rounded square at the same radius and height as the two buttons,
            not a circle. The app's account button is Clerk's, and Clerk does not
            inherit the app's CSS vars — so the real header sets its avatar
            radius to a 0.625rem literal, which is `--radius`, which is
            `rounded-lg`. A circle here is the one thing in this row that would
            not be in the app. `after:` and the fallback carry the primitive's
            own `rounded-full`, so both have to be squared off with it. */}
            <Avatar className="size-7 rounded-lg after:rounded-lg">
              <AvatarFallback className="rounded-lg">TA</AvatarFallback>
            </Avatar>
          </>
        )}
      </div>
    </header>
  )
}

export function AppShell({
  active,
  scope,
  developers,
  underShell = true,
  breadcrumb,
  hiddenItems,
  addedItems,
  onNavigate,
  children,
}: {
  /** Title of the sidebar item this screen lives under, e.g. "Personas". */
  active: string
  /** The admin view, in the top bar. Only a superadmin sees one. */
  scope?: React.ReactNode
  /** The Developers button in the top bar, in place of "Developer Doc". */
  developers?: "link" | "open"
  /** Whether the mockup shell's header sits above, which the sidebar has to
   *  clear. Off when the app is shown inside a frame on its own. */
  underShell?: boolean
  /** Crumbs after Home; a bare string is a single one. Defaults to `active`. */
  breadcrumb?: string | readonly string[]
  /**
   * Nav item titles this viewer's role cannot open, so the menu holds only
   * what they can reach. Omit it and the nav is the full one, which is what
   * every other mockup wants.
   */
  hiddenItems?: readonly string[]
  /**
   * Nav items a mockup proposes, each placed after an existing one. Only the
   * mockup that designs the page passes it, so every other nav stays the one
   * the app ships.
   */
  addedItems?: readonly { after: string; item: NavItem }[]
  /** Called with a nav item's title when it is clicked, so a mockup can make
   * the destinations it covers actually switch. Items it ignores stay inert. */
  onNavigate?: (title: string) => void
  children: React.ReactNode
}) {
  const hidden = new Set(hiddenItems ?? [])
  const groups = NAV.map((group) => ({
    ...group,
    items: group.items
      .flatMap((item) => [
        item,
        ...(addedItems ?? [])
          .filter((added) => added.after === item.title)
          .map((added) => added.item),
      ])
      .filter((item) => !hidden.has(item.title)),
  })).filter((group) => group.items.length > 0)

  return (
    /* The app sizes its sidebar at 15rem; the shadcn primitive ships 16rem.
       Set here rather than in the primitive, which is generated. */
    <SidebarProvider
      className="min-h-0 flex-1"
      style={{ "--sidebar-width": "15rem" } as React.CSSProperties}
    >
      {/* The sidebar pins to the viewport as it does in the app, so it
          starts below the mockup shell's 48px bar rather than sliding under
          it. */}
      <Sidebar
        className={underShell ? "pt-12" : undefined}
        collapsible="icon"
        variant="inset"
      >
        <SidebarHeader className="px-2 pt-2 pb-1">
          <div className="flex items-center justify-between group-data-[state=collapsed]:justify-center">
            {/* 56×32 is the size the app's own header renders it at. */}
            <Image
              alt="sarj.ai"
              className="group-data-[state=collapsed]:hidden"
              height={32}
              priority
              src="/logo.png"
              width={56}
            />
            <SidebarTrigger className="size-8 rounded-md text-muted-foreground hover:bg-accent hover:text-foreground [&>svg]:size-5" />
          </div>
        </SidebarHeader>

        <SidebarContent>
          <SidebarGroup className="pt-2 pb-0">
            <SidebarGroupContent>
              <SidebarMenu>
                <NavLink
                  active={PLAYGROUND.title === active}
                  item={PLAYGROUND}
                  onNavigate={onNavigate}
                />
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>

          {groups.map((group, index) => (
            <React.Fragment key={group.label}>
              {/* The rail hides section labels, so a rule stands in for the
                  grouping those labels carry when the nav is open. */}
              {index > 0 ? (
                <div className="mx-2 my-1 hidden h-px shrink-0 bg-sidebar-border group-data-[collapsible=icon]:block" />
              ) : null}
              <NavGroup
                active={active}
                /* A closed group hiding the item the screen is on reads as the
                   nav having lost its place, so the active item's group opens
                   regardless of where the group would otherwise start. */
                defaultOpen={
                  group.defaultOpen ||
                  group.items.some((item) => item.title === active)
                }
                items={group.items}
                label={group.label}
                onNavigate={onNavigate}
              />
            </React.Fragment>
          ))}
        </SidebarContent>
      </Sidebar>

      <SidebarInset className="min-w-0 overflow-hidden">
        <AppHeader
          developers={developers}
          scope={scope}
          trail={
            breadcrumb === undefined
              ? [active]
              : typeof breadcrumb === "string"
                ? [breadcrumb]
                : breadcrumb
          }
          showSettings={!hidden.has("Global Settings")}
        />
        {/* No gutter here: the page owns its p-3 lg:p-4, matching the header. */}
        <div className="min-h-0 flex-1 overflow-auto">{children}</div>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import {
  ArrowLeft02Icon,
  ArrowRight02Icon,
  ArrowUp01Icon,
  ArrowUpRight01Icon,
  BookOpen01Icon,
  Cancel01Icon,
  Copy01Icon,
  Cursor02Icon,
  Link04Icon,
  Search01Icon,
  SourceCodeIcon,
  Tick02Icon,
  TranslateIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/**
 * Icons for the workspace itself — the index and the shell around every
 * mockup. Icons *inside* a mockup live in that mockup's own icons.tsx; this
 * file is only the chrome.
 */
export const BackIcon = icon(ArrowLeft02Icon, "BackIcon")
export const OpenIcon = icon(ArrowRight02Icon, "OpenIcon")
export const SearchIcon = icon(Search01Icon, "SearchIcon")
export const ClearIcon = icon(Cancel01Icon, "ClearIcon")
export const DirectionIcon = icon(TranslateIcon, "DirectionIcon")

/* Beside the ticket ID in a card's footer, so it reads as something that
   leaves the page rather than as another in-page action. */
export const TicketLinkIcon = icon(ArrowUpRight01Icon, "TicketLinkIcon")

/* On the dock at the foot of the index, pointing at the list of surfaces
   that opens above it. */
export const DockIcon = icon(ArrowUp01Icon, "DockIcon")

/* The registry menu on an index card: the trigger, and the copy affordance
   that swaps to a tick once the command is on the clipboard. */
export const RegistryIcon = icon(SourceCodeIcon, "RegistryIcon")
export const CopyIcon = icon(Copy01Icon, "CopyIcon")
export const CopiedIcon = icon(Tick02Icon, "CopiedIcon")

/* On the index header, next to the search field — the way into the design
   system, which has no card in the list below. */
export const RulesIcon = icon(BookOpen01Icon, "RulesIcon")

/* Opens the card's links — the mockup's own URL and the tickets it answers —
   for copying rather than for following. */
export const ShareLinkIcon = icon(Link04Icon, "ShareLinkIcon")

/* The coach. It labels the nav button that replays the walkthrough, and it is
   the glyph the walkthrough parks on whatever control the reader is meant to
   press — the one place in the lab where an icon stands in for a pointer,
   because the pointer is what it is talking about. */
export const PointerIcon = icon(Cursor02Icon, "PointerIcon")

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
